<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue'
import { ArrowUp, ArrowUpRight, Plus, Sparkles, BookOpen, Package, ShieldCheck, MessageSquare, ListTree, Copy, Square, ChevronRight, FileText, AlertCircle } from 'lucide-vue-next'
import { useWorkspace } from '../stores/workspace'
import type { Message } from '../types'
import ModalPanel from '../components/ModalPanel.vue'
const store = useWorkspace(); const input = ref(''); const thread = ref<HTMLElement>(); const details = ref<Message>(); const confirming = ref<Message>()
const messages = computed(() => store.active?.messages || [])
const examples = [{ icon: BookOpen, title: '了解售后政策', text: '定制商品有质量问题，可以退货吗？' }, { icon: Package, title: '查询订单物流', text: '帮我查询订单 ORD10001 的物流进度' }, { icon: ShieldCheck, title: '处理订单取消', text: '帮我取消订单 ORD10003' }]
const last = computed(() => messages.value[messages.value.length - 1]); const inputError = computed(() => input.value.length > 4000 ? '消息不能超过 4000 个字符' : '')
async function send(text = input.value) { if (!text.trim() || text.length > 4000 || store.busy) return; input.value = ''; await store.send(text) }
function keydown(e: KeyboardEvent) { if (e.key === 'Enter' && !e.shiftKey && !e.isComposing) { e.preventDefault(); send() } }
async function copy(text: string) { try { await navigator.clipboard.writeText(text); store.notify('已复制回答') } catch { store.notify('无法访问剪贴板，请手动复制') } }
function confirmAction() { const m = confirming.value; confirming.value = undefined; if (m) store.send(m.originalQuery || '', m) }
watch(() => [messages.value.length, last.value?.content, last.value?.nodes?.length, last.value?.error], async () => { const nearBottom = !thread.value || thread.value.scrollHeight - thread.value.scrollTop - thread.value.clientHeight < 180; await nextTick(); if (nearBottom && thread.value) thread.value.scrollTop = thread.value.scrollHeight })
function time(value: string) { return new Date(value).toLocaleTimeString('zh-CN', { hour: '2-digit', minute: '2-digit' }) }
</script>
<template><div class="page chat-page">
  <div class="chat-layout"><section class="chat-card"><div class="chat-toolbar"><div class="toolbar-title"><span class="small-icon"><MessageSquare :size="16" /></span><strong>{{ store.active?.title || '新会话' }}</strong><span class="badge">{{ store.active ? `${Math.floor(messages.length / 2)} 轮对话` : '准备就绪' }}</span></div><button class="button new-chat-button" :disabled="store.busy" @click="store.newChat()"><Plus :size="16" />新建会话</button><button class="text-button" :disabled="!last?.response" @click="details = last"><ListTree :size="16" />回答详情</button></div>
    <div ref="thread" class="thread" :class="{ empty: !messages.length }" aria-live="polite" aria-relevant="additions text">
      <div v-if="!messages.length" class="welcome"><span class="welcome-icon"><Sparkles :size="25" /></span><span class="badge welcome-badge">ADAPTIVE INTELLIGENCE</span><h2>有什么可以帮你？</h2><p>咨询商品政策、跟踪订单，或处理售后事务。<br>请描述你的问题，我会尽力为你解答。</p><div class="example-grid"><button v-for="example in examples" :key="example.title" class="example-card" @click="input = example.text"><component :is="example.icon" :size="20" /><strong>{{ example.title }}</strong><span>{{ example.text }}</span><div><ArrowUpRight :size="15" /></div></button></div><div class="welcome-footnote"><ShieldCheck :size="14" />涉及业务变更的操作，会先征求你的确认。</div></div>
      <article v-for="message in messages" :key="message.id" class="message" :class="message.role"><div class="message-avatar"><Sparkles v-if="message.role === 'assistant'" :size="17" /><span v-else>{{ (store.active?.userId || 'U').slice(0, 1).toUpperCase() }}</span></div><div class="message-body"><div class="message-heading"><strong>{{ message.role === 'assistant' ? 'Adaptive 助手' : '你' }}</strong><span>{{ time(message.time) }}</span></div><div v-if="message.content" class="message-text">{{ message.content }}</div><div v-if="store.busy && message === last" class="processing"><span class="pulse-dot" />正在回复…<span v-if="message.content"> · 内容生成中</span></div><div v-if="!message.content && !message.error && store.busy && message === last" class="skeleton-lines"><div /><div /><div /></div><div v-if="message.error" class="inline-error"><AlertCircle :size="16" /><span>{{ message.error }}</span><button v-if="!message.content && !messages.some(m => m.actionStatus === 'uncertain')" class="text-button" :disabled="store.busy" @click="send(message.originalQuery)">重试</button></div>
        <div v-if="message.response?.pending_action" class="action-card"><div class="action-heading"><ShieldCheck :size="18" /><strong>需要你的确认</strong><span class="badge warning">业务变更</span></div><p>{{ message.response.pending_action.summary }}</p><code>{{ message.response.pending_action.tool_name }}</code><pre>{{ JSON.stringify(message.response.pending_action.arguments, null, 2) }}</pre><div v-if="!message.actionStatus" class="action-buttons"><button class="button" @click="message.actionStatus = 'cancelled'">暂不执行</button><button class="button primary" :disabled="store.busy" @click="confirming = message">确认操作</button></div><span v-else class="muted">{{ ({ cancelled: '已取消本地确认', submitted: '已提交确认，请查看后续回复', uncertain: '结果待核实，请勿重复提交' })[message.actionStatus] }}</span></div>
        <div v-if="message.response?.citations.length" class="citations"><span>参考来源</span><button v-for="(citation, i) in message.response.citations" :key="citation.chunk_id" class="citation" @click="details = message"><FileText :size="13" />{{ i + 1 }}. {{ citation.title }}</button></div><div v-if="message.response" class="answer-footer"><span>{{ ((message.response.latency.total_ms || 0) / 1000).toFixed(2) }}s</span><span>{{ message.response.token_usage.total_tokens }} tokens</span><button class="icon-button" aria-label="复制回答" @click="copy(message.content)"><Copy :size="14" /></button><button class="text-button" @click="details = message">查看回答详情<ChevronRight :size="14" /></button></div>
      </div></article>
    </div>
    <div class="composer-area"><div class="composer" :class="{ invalid: inputError }"><textarea v-model="input" aria-label="输入客服问题" placeholder="输入你的问题，例如：帮我查询订单 ORD10001…" rows="2" :disabled="store.busy" @keydown="keydown" /><div class="composer-bottom"><span>{{ store.settings.stream ? '流式回答' : '完整回答' }}</span><button v-if="store.busy" class="send-button" aria-label="停止接收" @click="store.stop()"><Square :size="15" /></button><button v-else class="send-button" aria-label="发送消息" :disabled="!input.trim() || !!inputError" @click="send()"><ArrowUp :size="18" /></button></div></div><div class="composer-help"><span :class="{ 'error-text': inputError }">{{ inputError || 'Enter 发送，Shift + Enter 换行' }}</span><span>{{ input.length }} / 4000</span></div></div>
  </section></div>
  <ModalPanel v-if="details" title="回答详情" drawer @close="details = undefined"><div class="detail-section"><h3>引用来源</h3><div v-for="citation in details.response?.citations" :key="citation.chunk_id" class="source-card"><FileText :size="16" /><strong>{{ citation.title }}</strong><p>{{ citation.section || '未提供章节' }}</p><code>{{ citation.chunk_id }}</code></div><p v-if="!details.response?.citations.length" class="muted">本次回答未提供知识库引用。</p></div></ModalPanel>
  <ModalPanel v-if="confirming" title="确认执行业务操作" @close="confirming = undefined"><p>确认后将向服务端提交以下操作，请核对参数。</p><div class="source-card"><strong>{{ confirming.response?.pending_action?.tool_name }}</strong><pre>{{ JSON.stringify(confirming.response?.pending_action?.arguments, null, 2) }}</pre></div><template #footer><button class="button" @click="confirming = undefined">返回</button><button class="button primary" @click="confirmAction">确认并提交</button></template></ModalPanel>
</div></template>
